/**
 * Video Analysis (TPI-V2-WEB-010 §14/§15/§16, Phase 010D).
 *
 * HONEST SOURCE POSITION: the original iPad application has **no implemented
 * video analysis screen** — `ForensicAnalysisHubView` renders a disabled
 * placeholder card ("Import • Playback • Markers" / "Coming soon in future
 * build"). This view therefore implements the closest reliable browser
 * equivalent of that stated intent (import, playback, timeline navigation,
 * frame inspection, frame capture), and everything it does is derived from real
 * decoded video data.
 *
 * Guarantees:
 *  - the original video is imported unchanged through the evidence pipeline;
 *  - captured frames are DERIVATIVES that record source id, seek time, method,
 *    format and digest;
 *  - frame accuracy is limited by the browser decoder's seek behaviour and is
 *    stated in the UI — no frame metadata or motion/object detection is invented.
 */
import "../dashboard/dashboard.css";
import { getDb } from "../../core/db";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { AuditService } from "../../core/audit";
import { getManagedFileStore } from "../../core/files/storeRegistry";
import { EvidenceAnnotationService } from "../../core/evidence/evidenceReviewService";
import type { EvidenceAnnotationRecord } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { navigate } from "../../app/router";

const db = () => getDb();

interface VideoUiState {
  selectedId: string | null;
  status: string;
  notes: string;
  /** Seek position used for the last frame capture. */
  lastCaptureSeconds: number | null;
  objectUrls: string[];
  /** Persistent markers loaded from the evidence annotation store. */
  markers: EvidenceAnnotationRecord[];
  /** Selected marker id (for navigate / edit / remove). */
  selectedMarkerId: string | null;
}

const ui = new WeakMap<HTMLElement, VideoUiState>();

function st(container: HTMLElement): VideoUiState {
  let s = ui.get(container);
  if (!s) {
    s = { selectedId: null, status: "", notes: "", lastCaptureSeconds: null, objectUrls: [], markers: [], selectedMarkerId: null };
    ui.set(container, s);
  }
  return s;
}

function releaseUrls(s: VideoUiState): void {
  for (const url of s.objectUrls) URL.revokeObjectURL(url);
  s.objectUrls = [];
}

/** Marker position as a percentage of the video duration (0 when unknown). */
function markerPercent(marker: EvidenceAnnotationRecord, video: { fileSizeBytes: number } | undefined): number {
  void video;
  const t = marker.target.startSeconds ?? 0;
  const duration = activeDurationSeconds > 0 ? activeDurationSeconds : 1;
  return Math.max(0, Math.min(100, (t / duration) * 100));
}

/** Duration of the video currently loaded (set by the player metadata handler). */
let activeDurationSeconds = 0;

function fmtTime(seconds: number): string {
  if (!Number.isFinite(seconds)) return "00:00.000";
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, "0")}:${s.toFixed(3).padStart(6, "0")}`;
}

export async function renderVideoAnalysis(container: HTMLElement, evidenceId?: string): Promise<void> {
  const s = st(container);
  if (evidenceId) s.selectedId = evidenceId;

  const videos = (await db().evidence.toArray())
    .filter((e) => e.mediaType === "video" && e.kind === "original")
    .sort((a, b) => b.createdAt - a.createdAt);
  if (!s.selectedId && videos.length > 0) s.selectedId = videos[0]!.id;
  const selected = videos.find((v) => v.id === s.selectedId);

  releaseUrls(s);
  let videoUrl = "";
  if (selected) {
    const bytes = await getManagedFileStore().read(selected.opfsPath);
    if (bytes) {
      videoUrl = URL.createObjectURL(new Blob([bytes], { type: selected.mimeType ?? "video/mp4" }));
      s.objectUrls.push(videoUrl);
    } else {
      s.status = "The managed copy is not present in browser storage.";
    }
  }

  // Persistent markers (010G-C): stored on the existing evidence-annotation
  // model as time-range annotations, so no new storage was introduced.
  const annotationService = new EvidenceAnnotationService(db());
  s.markers = selected ? (await annotationService.listForEvidence(selected.id)).filter((a) => a.annotationType === "videoRange") : [];
  if (s.selectedMarkerId && !s.markers.some((mm) => mm.id === s.selectedMarkerId)) s.selectedMarkerId = null;

  const { CaseRepository } = await import("../../core/repositories/caseRepository");
  const cases = await new CaseRepository(db()).listCases(200);

  invalidateView(container);
  mountView(
    container,
    viewShell(
      "Video Analysis",
      `
      <div class="case-form" data-root="video-analysis" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-meta"><strong>Note on origin parity:</strong> video analysis was a placeholder in the original
        iPad application ("Coming soon in future build"). This view implements the stated intent — import, playback,
        timeline navigation, frame inspection and frame capture — using real video data only.
        <strong>No motion events, objects, anomalies or detection confidence are generated</strong>, and no frame
        metadata is invented; frame accuracy is limited by the browser decoder's seek behaviour.</p>

        <h3 class="cc-section-title">Import Video</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="va-case">Case</label>
            <select id="va-case">
              ${cases.length === 0 ? '<option value="">— no cases yet —</option>' : cases.map((c) => `<option value="${c.id}">${esc(c.caseNumber)} — ${esc(c.title)}</option>`).join("")}
            </select></div>
          <div class="detail-field"><label for="va-room">Room (optional)</label>
            <select id="va-room"><option value="">Unassigned</option></select></div>
        </div>
        <div class="detail-field"><label for="va-files">Video files</label>
          <input id="va-files" type="file" accept="video/*" multiple></div>
        <div class="form-actions"><button class="button-primary" id="va-import" type="button">Import Video</button></div>
        <p class="cc-meta" id="va-status" role="status">${esc(s.status)}</p>
        <p class="cc-meta">Codec support varies by browser. An unplayable format is reported here rather than hidden; the file is still stored and hashed so it can be reviewed later.</p>

        <h3 class="cc-section-title">Case Videos (${videos.length})</h3>
        ${
          videos.length === 0
            ? '<div class="cc-empty">No videos imported for any case.</div>'
            : videos
                .map(
                  (v) => `
          <div class="case-row">
            <div>
              <div class="case-title">${esc(v.title)}</div>
              <div class="case-meta">${new Date(v.createdAt).toLocaleString()} • ${esc(v.mimeType ?? "unknown type")} • ${Math.round(v.fileSizeBytes / 1024)} KB • integrity: ${esc(v.verificationStatus ?? "unverified")}</div>
            </div>
            <button class="back-button" data-open-video="${v.id}" type="button">Open</button>
          </div>`,
                )
                .join("")
        }

        ${
          selected && videoUrl
            ? `
        <h3 class="cc-section-title">Playback — ${esc(selected.title)}</h3>
        <div class="case-form" data-video-player="${selected.id}">
          <video id="va-video" controls playsinline src="${videoUrl}" style="width:100%;max-height:60vh;background:#0B0E12;border:1px solid #2A3441;border-radius:8px;" aria-label="Video playback"></video>

          <div class="detail-field" style="margin-top:12px;">
            <label for="va-seek">Timeline position (seconds)</label>
            <input id="va-seek" type="range" min="0" max="100" step="0.001" value="0">
            <div class="case-meta"><span id="va-time">00:00.000</span> / <span id="va-duration">—</span></div>
          </div>
          <div class="form-actions">
            <button class="back-button" id="va-step-back" type="button">◀ Frame −0.040 s</button>
            <button class="back-button" id="va-step-fwd" type="button">Frame +0.040 s ▶</button>
            <button class="button-secondary" id="va-mark" type="button">Add Marker at Current Position…</button>
          </div>
          <div class="case-meta" id="va-markers"></div>

          <h3 class="cc-section-title">Timeline Markers (${s.markers.length})</h3>
          <p class="cc-meta">Markers are stored as <strong>annotations on the evidence record</strong> — they never alter the original video.
          The original iPad application had no marker model (the video screen was a placeholder), so this is the closest equivalent of its stated
          "Markers" intent; no automatic anomaly detection is performed.</p>
          <div id="va-marker-timeline" style="position:relative;height:26px;background:var(--background-deep);border:1px solid var(--border);border-radius:6px;margin:6px 0;">
            ${s.markers
              .map(
                (mm, i) =>
                  `<button class="va-marker-pin" data-marker-goto="${mm.id}" type="button" title="Marker ${i + 1}: ${esc(mm.description)}" aria-label="Marker ${i + 1}: ${esc(mm.description)}" style="position:absolute;left:${markerPercent(mm, selected)}%;top:2px;transform:translateX(-50%);background:${mm.id === s.selectedMarkerId ? "var(--cyan)" : "transparent"};border:1px solid var(--cyan);border-radius:3px;width:6px;height:20px;padding:0;cursor:pointer;"></button>`,
              )
              .join("")}
          </div>
          ${s.markers.length === 0
            ? '<div class="cc-empty">No markers yet.</div>'
            : s.markers
                .map(
                  (mm, i) => `
            <div class="case-row" data-marker-row="${mm.id}">
              <div>
                <div class="case-title">Marker ${i + 1} — ${fmtTime(mm.target.startSeconds ?? 0)}${mm.id === s.selectedMarkerId ? " ▸" : ""}</div>
                <div class="case-meta">${esc(mm.description)}${mm.notes ? ` • Notes: ${esc(mm.notes)}` : ""} • ${esc(mm.author)} • ${new Date(mm.createdAt).toLocaleString()} • revision ${mm.revision}</div>
              </div>
              <div style="display:flex;gap:6px;">
                <button class="back-button" data-marker-goto="${mm.id}" type="button">Go</button>
                <button class="back-button" data-marker-edit="${mm.id}" type="button">Edit…</button>
                <button class="back-button" data-marker-remove="${mm.id}" type="button">Remove…</button>
              </div>
            </div>`,
                )
                .join("")}

          <h3 class="cc-section-title">Frame Capture</h3>
          <div class="form-actions">
            <button class="button-primary" id="va-capture" type="button">Capture Frame at Current Position</button>
          </div>
          <p class="cc-meta">The captured frame is saved as <strong>derived evidence</strong> recording the source video id,
          the seek time, the extraction method and its own SHA-256 digest. Frame accuracy is limited by the browser's
          decoder seek behaviour: the frame shown at the marked time is what is captured, and browsers may land on the
          nearest decodable frame. No motion events, objects, anomalies or detection confidence are generated.</p>

          <h3 class="cc-section-title">Investigator Notes</h3>
          <div class="detail-field"><label for="va-notes">Notes</label>
            <textarea id="va-notes" rows="3">${esc(selected.notes ?? s.notes)}</textarea></div>
          <div class="form-actions">
            <button class="button-secondary" id="va-save-notes" type="button">Save Notes</button>
          </div>
          <div class="case-form">
            <div class="case-title">Source</div>
            <div class="case-meta">${esc(selected.originalFileName ?? selected.fileName)} • SHA-256 ${esc(selected.contentHash.slice(0, 24))}… • captured ${new Date(selected.captureTimestamp ?? selected.acquiredAt).toLocaleString()}</div>
          </div>
        </div>`
            : selected
              ? '<div class="cc-empty">This video could not be read from browser storage, so playback is unavailable.</div>'
              : ""
        }

        <div class="form-actions"><button class="back-button" id="va-back" type="button">← Back</button></div>
      </div>
    `,
  ));

  wireHandlers(container, s, () => renderVideoAnalysis(container, s.selectedId ?? undefined));
  wireBackButton(container);
}

function wireHandlers(container: HTMLElement, s: VideoUiState, reload: () => Promise<void>): void {
  onDelegate(container, "click", "#va-back", () => navigate("forensic"));
  onDelegate(container, "change", "#va-case", async (el) => {
    const caseId = (el as HTMLSelectElement).value;
    const roomSelect = container.querySelector<HTMLSelectElement>("#va-room");
    if (!caseId || !roomSelect) return;
    const structure = await db().propertyStructures.where("caseId").equals(caseId).first();
    const rooms = structure
      ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((r) => !r.archived)
      : [];
    roomSelect.innerHTML = `<option value="">Unassigned</option>${rooms.map((r) => `<option value="${r.id}">${esc(r.name)}</option>`).join("")}`;
  });

  onDelegate(container, "click", "#va-import", async () => {
    const caseId = container.querySelector<HTMLSelectElement>("#va-case")?.value ?? "";
    const roomId = container.querySelector<HTMLSelectElement>("#va-room")?.value || null;
    const files = Array.from(container.querySelector<HTMLInputElement>("#va-files")?.files ?? []);
    if (!caseId) {
      s.status = "Select a case before importing video.";
      await reload();
      return;
    }
    if (files.length === 0) {
      s.status = "Select at least one video file.";
      await reload();
      return;
    }
    const repo = new EvidenceRepository(db());
    let count = 0;
    for (const file of files) {
      const record = await repo.storeOriginal({
        caseId,
        mediaType: "video",
        title: file.name.replace(/\.[^.]+$/, "") || "Imported Video",
        fileName: file.name,
        data: file,
        origin: "import",
        recordedBy: "not recorded",
      });
      await db().evidence.put({
        ...record,
        originalFileName: file.name,
        sourceDescription: "Imported video; original source not recorded.",
        importedAt: Date.now(),
        verificationStatus: "verified",
        verifiedAt: Date.now(),
        verificationDetail: "Stored unchanged on import and hashed.",
        roomId,
        captureTimestamp: file.lastModified || null,
        captureTimestampSource: file.lastModified ? "fileMetadata" : "unknown",
      });
      count += 1;
    }
    s.status = `${count} video(s) imported.`;
    await reload();
  });

  onDelegate(container, "click", "[data-open-video]", (el) => {
    s.selectedId = el.dataset.openVideo ?? null;
    void reload();
  });

  const video = () => container.querySelector<HTMLVideoElement>("#va-video");
  /** Assigned in the marker section below; declared here so the player handlers can call it. */
  let renderMarkerStrip: () => Promise<void> = async () => undefined;

  const syncTimeline = () => {
    const v = video();
    const slider = container.querySelector<HTMLInputElement>("#va-seek");
    const time = container.querySelector<HTMLElement>("#va-time");
    const duration = container.querySelector<HTMLElement>("#va-duration");
    if (!v) return;
    if (slider && Number.isFinite(v.duration) && v.duration > 0) {
      slider.max = String(v.duration);
      if (document.activeElement !== slider) slider.value = String(v.currentTime);
    }
    if (time) time.textContent = fmtTime(v.currentTime);
    if (duration) duration.textContent = Number.isFinite(v.duration) ? fmtTime(v.duration) : "—";
  };

  // Keep the timeline readout in sync while playing.
  const v = video();
  if (v) {
    v.addEventListener("timeupdate", syncTimeline);
    v.addEventListener("loadedmetadata", () => {
      activeDurationSeconds = Number.isFinite(v.duration) ? v.duration : 0;
      syncTimeline();
      void renderMarkerStrip();
    });
    v.addEventListener("error", () => {
      s.status = "This browser cannot decode the video's codec. The file is stored and hashed; review it in a player that supports the format.";
    });
  }

  onDelegate(container, "input", "#va-seek", () => {
    const vEl = video();
    const slider = container.querySelector<HTMLInputElement>("#va-seek");
    if (vEl && slider) {
      vEl.currentTime = Number(slider.value);
      syncTimeline();
    }
  });

  const step = (delta: number) => {
    const vEl = video();
    if (!vEl) return;
    vEl.pause();
    vEl.currentTime = Math.max(0, Math.min(vEl.duration || 0, vEl.currentTime + delta));
    activeDurationSeconds = Number.isFinite(vEl.duration) ? vEl.duration : 0;
    syncTimeline();
    void renderMarkerStrip();
  };
  onDelegate(container, "click", "#va-step-back", () => step(-0.04));
  onDelegate(container, "click", "#va-step-fwd", () => step(0.04));

  // ---- Persistent markers (010G-C) ----
  const annotationSvc = new EvidenceAnnotationService(db());
  const markerVideoId = () => container.querySelector<HTMLElement>("[data-video-player]")?.dataset.videoPlayer ?? null;

  renderMarkerStrip = async () => {
    const strip = container.querySelector<HTMLElement>("#va-marker-timeline");
    if (!strip) return;
    const id = markerVideoId();
    if (!id) return;
    const list = (await annotationSvc.listForEvidence(id)).filter((a) => a.annotationType === "videoRange" && !a.archived);
    strip.innerHTML = list
      .map(
        (mm, i) =>
          `<button data-marker-goto="${mm.id}" type="button" title="Marker ${i + 1}: ${esc(mm.description)}" aria-label="Marker ${i + 1}: ${esc(mm.description)}" style="position:absolute;left:${markerPercent(mm, undefined)}%;top:2px;transform:translateX(-50%);background:${mm.id === s.selectedMarkerId ? "var(--cyan)" : "transparent"};border:1px solid var(--cyan);border-radius:3px;width:6px;height:20px;padding:0;cursor:pointer;"></button>`,
      )
      .join("");
  };

  onDelegate(container, "click", "#va-mark", async () => {
    const vEl = video();
    const id = markerVideoId();
    if (!vEl || !id) return;
    const seekSeconds = vEl.currentTime;
    const description = window.prompt(`Marker description at ${fmtTime(seekSeconds)}:`, "");
    if (description === null || !description.trim()) {
      s.status = "A marker description is required.";
      await reload();
      return;
    }
    const author = window.prompt("Investigator name (marker attribution):", "") ?? "";
    if (!author.trim()) {
      s.status = "Investigator attribution is required; no marker was saved.";
      await reload();
      return;
    }
    const notes = window.prompt("Investigator notes (optional):", "") ?? "";
    await annotationSvc.create(id, {
      author: author.trim(),
      annotationType: "videoRange",
      target: { startSeconds: seekSeconds, endSeconds: seekSeconds },
      description: description.trim(),
      notes,
    });
    s.status = `Marker added at ${fmtTime(seekSeconds)}.`;
    await reload();
  });

  onDelegate(container, "click", "[data-marker-goto]", (el) => {
    const id = el.dataset.markerGoto ?? "";
    const marker = s.markers.find((mm) => mm.id === id);
    if (!marker) return;
    s.selectedMarkerId = id;
    const vEl = video();
    if (vEl) {
      vEl.currentTime = marker.target.startSeconds ?? 0;
      vEl.pause();
    }
    void reload();
  });

  onDelegate(container, "click", "[data-marker-edit]", async (el) => {
    const id = el.dataset.markerEdit ?? "";
    const marker = s.markers.find((mm) => mm.id === id);
    if (!marker) return;
    const description = window.prompt("Revised marker description:", marker.description);
    if (description === null) return;
    const notes = window.prompt("Investigator notes:", marker.notes ?? "");
    if (notes === null) return;
    const reason = window.prompt("Reason for this marker revision:", "");
    if (!reason?.trim()) {
      alert("A revision requires a documented reason — the prior marker value is preserved.");
      return;
    }
    try {
      await annotationSvc.revise(id, { description, notes, reason });
      s.status = "Marker revised; the previous revision is preserved.";
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "[data-marker-remove]", async (el) => {
    const id = el.dataset.markerRemove ?? "";
    const marker = s.markers.find((mm) => mm.id === id);
    if (!marker) return;
    if (!window.confirm(`Remove marker "${marker.description}"? An audit event records the removal; the video is unchanged.`)) return;
    // Markers are annotations: revision preserves history, so removal revises to an
    // explicit "removed" state rather than destroying the record.
    await annotationSvc.revise(id, {
      description: marker.description,
      archived: true,
      reason: "Marker removed by investigator (video unchanged; prior value preserved).",
    });
    s.status = "Marker removed (prior value preserved in the revision history).";
    await reload();
  });

  onDelegate(container, "click", "#va-capture", async () => {
    const vEl = video();
    const player = container.querySelector<HTMLElement>("[data-video-player]");
    const caseIdOfVideo = player?.dataset.videoPlayer;
    if (!vEl || !caseIdOfVideo) return;
    const record = await db().evidence.get(caseIdOfVideo);
    if (!record) return;
    if (!vEl.videoWidth || !vEl.videoHeight) {
      s.status = "The video has no decodable frame at this position, so nothing was captured.";
      await reload();
      return;
    }
    const seekSeconds = vEl.currentTime;
    const canvas = document.createElement("canvas");
    canvas.width = vEl.videoWidth;
    canvas.height = vEl.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      s.status = "Frame could not be rendered.";
      await reload();
      return;
    }
    ctx.drawImage(vEl, 0, 0, canvas.width, canvas.height);
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob((b) => resolve(b), "image/png"));
    if (!blob) {
      s.status = "Frame could not be encoded.";
      await reload();
      return;
    }
    const notes = container.querySelector<HTMLTextAreaElement>("#va-notes")?.value ?? s.notes;
    const repo = new EvidenceRepository(db());
    const baseName = (record.originalFileName ?? record.fileName).replace(/\.[^.]+$/, "");
    const fileName = `${baseName}-frame-${seekSeconds.toFixed(3)}s.png`;
    const derived = await repo.createDerived({
      sourceId: record.id,
      mediaType: "photo",
      title: `${record.title} — frame @ ${fmtTime(seekSeconds)}`,
      fileName,
      data: new Blob([blob], { type: "image/png" }),
    });
    await db().evidence.put({
      ...derived,
      originalFileName: fileName,
      sourceDescription: `Frame extracted from ${record.originalFileName ?? record.fileName}`,
      importedAt: Date.now(),
      verificationStatus: "verified",
      verifiedAt: Date.now(),
      verificationDetail: "Rendered from the decoded video frame and hashed on write.",
      roomId: record.roomId ?? null,
      captureTimestamp: Date.now(),
      captureTimestampSource: "investigator",
      derivationMethod: "video-frame-extraction",
      derivationParameters: {
        sourceEvidenceId: record.id,
        seekSeconds,
        method: "canvas.drawImage on the seeked video element",
        format: "image/png",
        sourceWidth: canvas.width,
        sourceHeight: canvas.height,
      },
      notes: `Frame extracted at ${fmtTime(seekSeconds)} (browser seek position; accuracy limited by the decoder). Analyst notes: ${notes || "(none)"}`,
    });
    const audit = new AuditService(db());
    await audit.record("evidenceProcessed", "Video frame extracted as derived evidence.", {
      caseId: record.caseId,
      affectedRecordId: derived.id,
      metadata: { parentId: record.id, seekSeconds: Math.round(seekSeconds * 1000) / 1000 },
    });
    s.lastCaptureSeconds = seekSeconds;
    s.status = `Frame at ${fmtTime(seekSeconds)} saved as "${fileName}". The source video is unchanged.`;
    await reload();
  });

  onDelegate(container, "click", "#va-save-notes", async () => {
    const player = container.querySelector<HTMLElement>("[data-video-player]");
    const id = player?.dataset.videoPlayer;
    const notes = container.querySelector<HTMLTextAreaElement>("#va-notes")?.value ?? "";
    if (!id) return;
    const record = await db().evidence.get(id);
    if (!record) return;
    await db().evidence.put({ ...record, notes, updatedAt: Date.now() });
    s.notes = notes;
    s.status = "Notes saved.";
    await reload();
  });
}
